        104,            /* SunOS 5.x (command line) */
        88,             /* SunOS 5.x (short name) */
#endif /* USE_NT_PSINFO */

        100,            /* SunOS 5.x (command line) */
        84,             /* SunOS 5.x (short name) */

        44,             /* Linux (command line) */
        28,             /* Linux 2.0.36 (short name) */

        8,              /* FreeBSD */
