static const size_t     prpsoffsets64[] = {
#ifdef USE_NT_PSINFO
        152,            /* SunOS 5.x (command line) */
        136,            /* SunOS 5.x (short name) */
#endif /* USE_NT_PSINFO */

        136,            /* SunOS 5.x, 64-bit (command line) */
---
        136,            /* SunOS 5.x, 64-bit (command line) */
        120,            /* SunOS 5.x, 64-bit (short name) */

        56,             /* Linux (command line) */
