#define NOFFSETS32      (sizeof prpsoffsets32 / sizeof prpsoffsets32[0])
#define NOFFSETS64      (sizeof prpsoffsets64 / sizeof prpsoffsets64[0])

#define NOFFSETS        (clazz == ELFCLASS32 ? NOFFSETS32 : NOFFSETS64)

/*
 * Look through the program headers of an executable image, searching
 * for a PT_NOTE section of type NT_PRPSINFO, with a name "CORE" or
 * "FreeBSD"; if one is found, try looking in various places in its
 * contents for a 16-character string containing only printable
 * characters - if found, that string should be the name of the program
 * that dropped core.  Note: right after that 16-character string is,
 * at least in SunOS 5.x (and possibly other SVR4-flavored systems) and
 * Linux, a longer string (80 characters, in 5.x, probably other
 * SVR4-flavored systems, and Linux) containing the start of the
 * command line for that program.
 *
 * SunOS 5.x core files contain two PT_NOTE sections, with the types
 * NT_PRPSINFO (old) and NT_PSINFO (new).  These structs contain the
 * same info about the command name and command line, so it probably
 * isn't worthwhile to look for NT_PSINFO, but the offsets are provided
 * above (see USE_NT_PSINFO), in case we ever decide to do so.  The
 * NT_PRPSINFO and NT_PSINFO sections are always in order and adjacent;
 * the SunOS 5.x file command relies on this (and prefers the latter).
 *
 * The signal number probably appears in a section of type NT_PRSTATUS,
 * but that's also rather OS-dependent, in ways that are harder to
 * dissect with heuristics, so I'm not bothering with the signal number.
 * (I suppose the signal number could be of interest in situations where
 * you don't have the binary of the program that dropped core; if you
 * *do* have that binary, the debugger will probably tell you what
 * signal it was.)
 */

#define OS_STYLE_SVR4           0
#define OS_STYLE_FREEBSD        1
#define OS_STYLE_NETBSD         2

private const char os_style_names[][8] = {
        "SVR4",
        "FreeBSD",
        "NetBSD",
};

#define FLAGS_CORE_STYLE                0x003

#define FLAGS_DID_CORE                  0x004
#define FLAGS_DID_OS_NOTE               0x008
#define FLAGS_DID_BUILD_ID              0x010
#define FLAGS_DID_CORE_STYLE            0x020
#define FLAGS_DID_NETBSD_PAX            0x040
#define FLAGS_DID_NETBSD_MARCH          0x080
#define FLAGS_DID_NETBSD_CMODEL         0x100
#define FLAGS_DID_NETBSD_UNKNOWN        0x200
#define FLAGS_IS_CORE                   0x400
#define FLAGS_DID_AUXV                  0x800

private int
dophn_core(struct magic_set *ms, int clazz, int swap, int fd, off_t off,
    int num, size_t size, off_t fsize, int *flags, uint16_t *notecount)
{
        Elf32_Phdr ph32;
        Elf64_Phdr ph64;
        size_t offset, len;
        unsigned char nbuf[BUFSIZ];
        ssize_t bufsize;
        off_t ph_off = off;
        int ph_num = num;

        if (size != xph_sizeof) {
                if (file_printf(ms, ", corrupted program header size") == -1)
                        return -1;
                return 0;
        }

        /*
         * Loop through all the program headers.
         */
        for ( ; num; num--) {
                if (pread(fd, xph_addr, xph_sizeof, off) < (ssize_t)xph_sizeof) {
                        file_badread(ms);
                        return -1;
                }
                off += size;

                if (fsize != SIZE_UNKNOWN && xph_offset > fsize) {
                        /* Perhaps warn here */
                        continue;
                }

                if (xph_type != PT_NOTE)
                        continue;

                /*
                 * This is a PT_NOTE section; loop through all the notes
                 * in the section.
                 */
                len = xph_filesz < sizeof(nbuf) ? xph_filesz : sizeof(nbuf);
                if ((bufsize = pread(fd, nbuf, len, xph_offset)) == -1) {
                        file_badread(ms);
                        return -1;
                }
                offset = 0;
                for (;;) {
                        if (offset >= (size_t)bufsize)
                                break;
                        offset = donote(ms, nbuf, offset, (size_t)bufsize,
                            clazz, swap, 4, flags, notecount, fd, ph_off,
                            ph_num, fsize);
                        if (offset == 0)
                                break;

                }
        }
        return 0;
}
#endif

static void
do_note_netbsd_version(struct magic_set *ms, int swap, void *v)
{
        uint32_t desc;
        (void)memcpy(&desc, v, sizeof(desc));
        desc = elf_getu32(swap, desc);

        if (file_printf(ms, ", for NetBSD") == -1)
                return;
        /*
         * The version number used to be stuck as 199905, and was thus
         * basically content-free.  Newer versions of NetBSD have fixed
         * this and now use the encoding of __NetBSD_Version__:
         *
         *      MMmmrrpp00
         *
         * M = major version
         * m = minor version
         * r = release ["",A-Z,Z[A-Z] but numeric]
         * p = patchlevel
         */
        if (desc > 100000000U) {
                uint32_t ver_patch = (desc / 100) % 100;
                uint32_t ver_rel = (desc / 10000) % 100;
                uint32_t ver_min = (desc / 1000000) % 100;
                uint32_t ver_maj = desc / 100000000;

                if (file_printf(ms, " %u.%u", ver_maj, ver_min) == -1)
                        return;
                if (ver_rel == 0 && ver_patch != 0) {
                        if (file_printf(ms, ".%u", ver_patch) == -1)
                                return;
                } else if (ver_rel != 0) {
                        while (ver_rel > 26) {
                                if (file_printf(ms, "Z") == -1)
                                        return;
                                ver_rel -= 26;
                        }
                        if (file_printf(ms, "%c", 'A' + ver_rel - 1)
                            == -1)
                                return;
                }
        }
}

static void
do_note_freebsd_version(struct magic_set *ms, int swap, void *v)
{
        uint32_t desc;

        (void)memcpy(&desc, v, sizeof(desc));
        desc = elf_getu32(swap, desc);
        if (file_printf(ms, ", for FreeBSD") == -1)
                return;

        /*
         * Contents is __FreeBSD_version, whose relation to OS
         * versions is defined by a huge table in the Porter's
         * Handbook.  This is the general scheme:
         *
         * Releases:
         *      Mmp000 (before 4.10)
         *      Mmi0p0 (before 5.0)
         *      Mmm0p0
         *
         * Development branches:
         *      Mmpxxx (before 4.6)
         *      Mmp1xx (before 4.10)
         *      Mmi1xx (before 5.0)
         *      M000xx (pre-M.0)
         *      Mmm1xx
         *
         * M = major version
         * m = minor version
         * i = minor version increment (491000 -> 4.10)
         * p = patchlevel
         * x = revision
         *
         * The first release of FreeBSD to use ELF by default
         * was version 3.0.
         */
        if (desc == 460002) {
                if (file_printf(ms, " 4.6.2") == -1)
                        return;
        } else if (desc < 460100) {
                if (file_printf(ms, " %d.%d", desc / 100000,
                    desc / 10000 % 10) == -1)
                        return;
                if (desc / 1000 % 10 > 0)
                        if (file_printf(ms, ".%d", desc / 1000 % 10) == -1)
                                return;
                if ((desc % 1000 > 0) || (desc % 100000 == 0))
                        if (file_printf(ms, " (%d)", desc) == -1)
                                return;
        } else if (desc < 500000) {
                if (file_printf(ms, " %d.%d", desc / 100000,
                    desc / 10000 % 10 + desc / 1000 % 10) == -1)
                        return;
                if (desc / 100 % 10 > 0) {
                        if (file_printf(ms, " (%d)", desc) == -1)
                                return;
                } else if (desc / 10 % 10 > 0) {
                        if (file_printf(ms, ".%d", desc / 10 % 10) == -1)
                                return;
                }
        } else {
                if (file_printf(ms, " %d.%d", desc / 100000,
                    desc / 1000 % 100) == -1)
                        return;
                if ((desc / 100 % 10 > 0) ||
                    (desc % 100000 / 100 == 0)) {
                        if (file_printf(ms, " (%d)", desc) == -1)
                                return;
                } else if (desc / 10 % 10 > 0) {
                        if (file_printf(ms, ".%d", desc / 10 % 10) == -1)
                                return;
                }
        }
}

private int
/*ARGSUSED*/
do_bid_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap __attribute__((__unused__)), uint32_t namesz, uint32_t descsz,
    size_t noff, size_t doff, int *flags)
{
        if (namesz == 4 && strcmp((char *)&nbuf[noff], "GNU") == 0 &&
            type == NT_GNU_BUILD_ID && (descsz >= 4 || descsz <= 20)) {
                uint8_t desc[20];
                const char *btype;
                uint32_t i;
                *flags |= FLAGS_DID_BUILD_ID;
                switch (descsz) {
                case 8:
                    btype = "xxHash";
                    break;
                case 16:
                    btype = "md5/uuid";
                    break;
                case 20:
                    btype = "sha1";
                    break;
                default:
                    btype = "unknown";
                    break;
                }
                if (file_printf(ms, ", BuildID[%s]=", btype) == -1)
                        return 1;
                (void)memcpy(desc, &nbuf[doff], descsz);
                for (i = 0; i < descsz; i++)
                    if (file_printf(ms, "%02x", desc[i]) == -1)
                        return 1;
                return 1;
        }
        return 0;
}

private int
do_os_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap, uint32_t namesz, uint32_t descsz,
    size_t noff, size_t doff, int *flags)
{
        if (namesz == 5 && strcmp((char *)&nbuf[noff], "SuSE") == 0 &&
            type == NT_GNU_VERSION && descsz == 2) {
            *flags |= FLAGS_DID_OS_NOTE;
            file_printf(ms, ", for SuSE %d.%d", nbuf[doff], nbuf[doff + 1]);
            return 1;
        }

        if (namesz == 4 && strcmp((char *)&nbuf[noff], "GNU") == 0 &&
            type == NT_GNU_VERSION && descsz == 16) {
                uint32_t desc[4];
                (void)memcpy(desc, &nbuf[doff], sizeof(desc));

                *flags |= FLAGS_DID_OS_NOTE;
                if (file_printf(ms, ", for GNU/") == -1)
                        return 1;
                switch (elf_getu32(swap, desc[0])) {
                case GNU_OS_LINUX:
                        if (file_printf(ms, "Linux") == -1)
                                return 1;
                        break;
                case GNU_OS_HURD:
                        if (file_printf(ms, "Hurd") == -1)
                                return 1;
                        break;
                case GNU_OS_SOLARIS:
                        if (file_printf(ms, "Solaris") == -1)
                                return 1;
                        break;
                case GNU_OS_KFREEBSD:
                        if (file_printf(ms, "kFreeBSD") == -1)
                                return 1;
                        break;
                case GNU_OS_KNETBSD:
                        if (file_printf(ms, "kNetBSD") == -1)
                                return 1;
                        break;
                default:
                        if (file_printf(ms, "<unknown>") == -1)
                                return 1;
                }
                if (file_printf(ms, " %d.%d.%d", elf_getu32(swap, desc[1]),
                    elf_getu32(swap, desc[2]), elf_getu32(swap, desc[3])) == -1)
                        return 1;
                return 1;
        }

        if (namesz == 7 && strcmp((char *)&nbuf[noff], "NetBSD") == 0) {
                if (type == NT_NETBSD_VERSION && descsz == 4) {
                        *flags |= FLAGS_DID_OS_NOTE;
                        do_note_netbsd_version(ms, swap, &nbuf[doff]);
                        return 1;
                }
        }

        if (namesz == 8 && strcmp((char *)&nbuf[noff], "FreeBSD") == 0) {
                if (type == NT_FREEBSD_VERSION && descsz == 4) {
                        *flags |= FLAGS_DID_OS_NOTE;
                        do_note_freebsd_version(ms, swap, &nbuf[doff]);
                        return 1;
                }
        }

        if (namesz == 8 && strcmp((char *)&nbuf[noff], "OpenBSD") == 0 &&
            type == NT_OPENBSD_VERSION && descsz == 4) {
                *flags |= FLAGS_DID_OS_NOTE;
                if (file_printf(ms, ", for OpenBSD") == -1)
                        return 1;
                /* Content of note is always 0 */
                return 1;
        }

        if (namesz == 10 && strcmp((char *)&nbuf[noff], "DragonFly") == 0 &&
            type == NT_DRAGONFLY_VERSION && descsz == 4) {
                uint32_t desc;
                *flags |= FLAGS_DID_OS_NOTE;
                if (file_printf(ms, ", for DragonFly") == -1)
                        return 1;
                (void)memcpy(&desc, &nbuf[doff], sizeof(desc));
                desc = elf_getu32(swap, desc);
                if (file_printf(ms, " %d.%d.%d", desc / 100000,
                    desc / 10000 % 10, desc % 10000) == -1)
                        return 1;
                return 1;
        }
        return 0;
}

private int
do_pax_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap, uint32_t namesz, uint32_t descsz,
    size_t noff, size_t doff, int *flags)
{
        if (namesz == 4 && strcmp((char *)&nbuf[noff], "PaX") == 0 &&
            type == NT_NETBSD_PAX && descsz == 4) {
                static const char *pax[] = {
                    "+mprotect",
                    "-mprotect",
                    "+segvguard",
                    "-segvguard",
                    "+ASLR",
                    "-ASLR",
                };
                uint32_t desc;
                size_t i;
                int did = 0;

                *flags |= FLAGS_DID_NETBSD_PAX;
                (void)memcpy(&desc, &nbuf[doff], sizeof(desc));
                desc = elf_getu32(swap, desc);

                if (desc && file_printf(ms, ", PaX: ") == -1)
                        return 1;

                for (i = 0; i < __arraycount(pax); i++) {
                        if (((1 << (int)i) & desc) == 0)
                                continue;
                        if (file_printf(ms, "%s%s", did++ ? "," : "",
                            pax[i]) == -1)
                                return 1;
                }
                return 1;
        }
        return 0;
}

private int
do_core_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap, uint32_t namesz, uint32_t descsz,
    size_t noff, size_t doff, int *flags, size_t size, int clazz)
{
#ifdef ELFCORE
        int os_style = -1;
        /*
         * Sigh.  The 2.0.36 kernel in Debian 2.1, at
         * least, doesn't correctly implement name
         * sections, in core dumps, as specified by
         * the "Program Linking" section of "UNIX(R) System
         * V Release 4 Programmer's Guide: ANSI C and
         * Programming Support Tools", because my copy
         * clearly says "The first 'namesz' bytes in 'name'
         * contain a *null-terminated* [emphasis mine]
         * character representation of the entry's owner
         * or originator", but the 2.0.36 kernel code
         * doesn't include the terminating null in the
         * name....
         */
        if ((namesz == 4 && strncmp((char *)&nbuf[noff], "CORE", 4) == 0) ||
            (namesz == 5 && strcmp((char *)&nbuf[noff], "CORE") == 0)) {
                os_style = OS_STYLE_SVR4;
        }

        if ((namesz == 8 && strcmp((char *)&nbuf[noff], "FreeBSD") == 0)) {
                os_style = OS_STYLE_FREEBSD;
        }

        if ((namesz >= 11 && strncmp((char *)&nbuf[noff], "NetBSD-CORE", 11)
            == 0)) {
                os_style = OS_STYLE_NETBSD;
        }

        if (os_style != -1 && (*flags & FLAGS_DID_CORE_STYLE) == 0) {
                if (file_printf(ms, ", %s-style", os_style_names[os_style])
                    == -1)
                        return 1;
                *flags |= FLAGS_DID_CORE_STYLE;
                *flags |= os_style;
        }

        switch (os_style) {
        case OS_STYLE_NETBSD:
                if (type == NT_NETBSD_CORE_PROCINFO) {
                        char sbuf[512];
                        struct NetBSD_elfcore_procinfo pi;
                        memset(&pi, 0, sizeof(pi));
                        memcpy(&pi, nbuf + doff, descsz);

                        if (file_printf(ms, ", from '%.31s', pid=%u, uid=%u, "
                            "gid=%u, nlwps=%u, lwp=%u (signal %u/code %u)",
                            file_printable(sbuf, sizeof(sbuf),
                            CAST(char *, pi.cpi_name)),
                            elf_getu32(swap, pi.cpi_pid),
                            elf_getu32(swap, pi.cpi_euid),
                            elf_getu32(swap, pi.cpi_egid),
                            elf_getu32(swap, pi.cpi_nlwps),
                            elf_getu32(swap, pi.cpi_siglwp),
                            elf_getu32(swap, pi.cpi_signo),
                            elf_getu32(swap, pi.cpi_sigcode)) == -1)
                                return 1;

                        *flags |= FLAGS_DID_CORE;
                        return 1;
                }
                break;

        default:
                if (type == NT_PRPSINFO && *flags & FLAGS_IS_CORE) {
                        size_t i, j;
                        unsigned char c;
                        /*
                         * Extract the program name.  We assume
                         * it to be 16 characters (that's what it
                         * is in SunOS 5.x and Linux).
                         *
                         * Unfortunately, it's at a different offset
                         * in various OSes, so try multiple offsets.
                         * If the characters aren't all printable,
                         * reject it.
                         */
                        for (i = 0; i < NOFFSETS; i++) {
                                unsigned char *cname, *cp;
                                size_t reloffset = prpsoffsets(i);
                                size_t noffset = doff + reloffset;

size_t noffset = doff + reloffset;
                                size_t k;
                                for (j = 0; j < 16; j++, noffset++,
                                    reloffset++) {
                                        /*
                                         * Make sure we're not past
                                         * the end of the buffer; if
                                         * we are, just give up.
                                         */
                                        if (noffset >= size)
                                                goto tryanother;

                                        /*
                                         * Make sure we're not past
                                         * the end of the contents;
                                         * if we are, this obviously
                                         * isn't the right offset.
                                         */
                                        if (reloffset >= descsz)
                                                goto tryanother;

                                        c = nbuf[noffset];
                                        if (c == '\0') {
                                                /*
                                                 * A '\0' at the
                                                 * beginning is
                                                 * obviously wrong.
                                                 * Any other '\0'
                                                 * means we're done.
                                                 */
                                                if (j == 0)
                                                        goto tryanother;
                                                else
                                                        break;
                                        } else {
                                                /*
                                                 * A nonprintable
                                                 * character is also
                                                 * wrong.
                                                 */
                                                if (!isprint(c) || isquote(c))
                                                        goto tryanother;
                                        }
                                }
                                /*
                                 * Well, that worked.
                                 */

                                /*
                                 * Try next offsets, in case this match is
                                 * in the middle of a string.
                                 */
                                for (k = i + 1 ; k < NOFFSETS; k++) {
                                        size_t no;
                                        int adjust = 1;
                                        if (prpsoffsets(k) >= prpsoffsets(i))
                                                continue;
                                        for (no = doff + prpsoffsets(k);
                                             no < doff + prpsoffsets(i); no++)
                                                adjust = adjust
                                                         && isprint(nbuf[no]);
                                        if (adjust)
                                                i = k;
                                }

                                cname = (unsigned char *)
                                    &nbuf[doff + prpsoffsets(i)];
                                for (cp = cname; *cp && isprint(*cp); cp++)
                                        continue;
                                /*
                                 * Linux apparently appends a space at the end
                                 * of the command line: remove it.
                                 */
                                while (cp > cname && isspace(cp[-1]))
                                        cp--;
                                if (file_printf(ms, ", from '%.*s'",
                                    (int)(cp - cname), cname) == -1)
                                        return 1;
                                *flags |= FLAGS_DID_CORE;
                                return 1;

                        tryanother:
                                ;
                        }
                }
                break;
        }
#endif
        return 0;
}

private off_t
get_offset_from_virtaddr(struct magic_set *ms, int swap, int clazz, int fd,
    off_t off, int num, off_t fsize, uint64_t virtaddr)
{
        Elf32_Phdr ph32;
        Elf64_Phdr ph64;

        /*
         * Loop through all the program headers and find the header with
         * virtual address in which the "virtaddr" belongs to.
         */
        for ( ; num; num--) {
                if (pread(fd, xph_addr, xph_sizeof, off) < (ssize_t)xph_sizeof) {
                        file_badread(ms);
                        return -1;
                }
                off += xph_sizeof;

                if (fsize != SIZE_UNKNOWN && xph_offset > fsize) {
                        /* Perhaps warn here */
                        continue;
                }

                if (virtaddr >= xph_vaddr && virtaddr < xph_vaddr + xph_filesz)
                        return xph_offset + (virtaddr - xph_vaddr);
        }
        return 0;
}

private size_t
get_string_on_virtaddr(struct magic_set *ms,
    int swap, int clazz, int fd, off_t ph_off, int ph_num,
    off_t fsize, uint64_t virtaddr, char *buf, ssize_t buflen)
{
        char *bptr;
        off_t offset;

        if (buflen == 0)
                return 0;

        offset = get_offset_from_virtaddr(ms, swap, clazz, fd, ph_off, ph_num,
            fsize, virtaddr);
        if ((buflen = pread(fd, buf, CAST(size_t, buflen), offset)) <= 0) {
                file_badread(ms);
                return 0;
        }

        buf[buflen - 1] = '\0';

        /* We expect only printable characters, so return if buffer contains
         * non-printable character before the '\0' or just '\0'. */
        for (bptr = buf; *bptr && isprint((unsigned char)*bptr); bptr++)
                continue;
        if (*bptr != '\0')
                return 0;

        return bptr - buf;
}


private int
do_auxv_note(struct magic_set *ms, unsigned char *nbuf, uint32_t type,
    int swap, uint32_t namesz __attribute__((__unused__)),
    uint32_t descsz __attribute__((__unused__)),
    size_t noff __attribute__((__unused__)), size_t doff,
    int *flags, size_t size __attribute__((__unused__)), int clazz,
    int fd, off_t ph_off, int ph_num, off_t fsize)
{
#ifdef ELFCORE
        Aux32Info auxv32;
        Aux64Info auxv64;
        size_t elsize = xauxv_sizeof;
        const char *tag;
        int is_string;
        size_t nval;

        if ((*flags & (FLAGS_IS_CORE|FLAGS_DID_CORE_STYLE)) !=
            (FLAGS_IS_CORE|FLAGS_DID_CORE_STYLE))
                return 0;

        switch (*flags & FLAGS_CORE_STYLE) {
        case OS_STYLE_SVR4:
                if (type != NT_AUXV)
                        return 0;
                break;
#ifdef notyet
        case OS_STYLE_NETBSD:
                if (type != NT_NETBSD_CORE_AUXV)
                        return 0;
                break;
        case OS_STYLE_FREEBSD:
                if (type != NT_FREEBSD_PROCSTAT_AUXV)
                        return 0;
                break;
#endif
        default:
                return 0;
        }

        *flags |= FLAGS_DID_AUXV;

        nval = 0;
        for (size_t off = 0; off + elsize <= descsz; off += elsize) {
                (void)memcpy(xauxv_addr, &nbuf[doff + off], xauxv_sizeof);
                /* Limit processing to 50 vector entries to prevent DoS */
                if (nval++ >= 50) {
                        file_error(ms, 0, "Too many ELF Auxv elements");
                        return 1;
                }

                switch(xauxv_type) {
                case AT_LINUX_EXECFN:
                        is_string = 1;
                        tag = "execfn";
                        break;
                case AT_LINUX_PLATFORM:
                        is_string = 1;
                        tag = "platform";
                        break;
                case AT_LINUX_UID:
                        is_string = 0;
                        tag = "real uid";
                        break;
                case AT_LINUX_GID:
                        is_string = 0;
                        tag = "real gid";
                        break;
                case AT_LINUX_EUID:
                        is_string = 0;
                        tag = "effective uid";
                        break;
                case AT_LINUX_EGID:
                        is_string = 0;
                        tag = "effective gid";
                        break;
                default:
                        is_string = 0;
                        tag = NULL;
                        break;
                }

                if (tag == NULL)
                        continue;

                if (is_string) {
                        char buf[256];
                        ssize_t buflen;
                        buflen = get_string_on_virtaddr(ms, swap, clazz, fd,
                            ph_off, ph_num, fsize, xauxv_val, buf, sizeof(buf));

                        if (buflen == 0)
                                continue;

                        if (file_printf(ms, ", %s: '%s'", tag, buf) == -1)
                                return 0;
                } else {
                        if (file_printf(ms, ", %s: %d", tag, (int) xauxv_val)
                            == -1)
                                return 0;
                }
        }
        return 1;
#else
        return 0;
#endif
}

private size_t
donote(struct magic_set *ms, void *vbuf, size_t offset, size_t size,
    int clazz, int swap, size_t align, int *flags, uint16_t *notecount,
    int fd, off_t ph_off, int ph_num, off_t fsize)
{
        Elf32_Nhdr nh32;
        Elf64_Nhdr nh64;
        size_t noff, doff;
        uint32_t namesz, descsz;
        unsigned char *nbuf = CAST(unsigned char *, vbuf);

        if (*notecount == 0)
                return 0;
        --*notecount;

        if (xnh_sizeof + offset > size) {
                /*
                 * We're out of note headers.
                 */
                return xnh_sizeof + offset;
        }

        (void)memcpy(xnh_addr, &nbuf[offset], xnh_sizeof);
        offset += xnh_sizeof;

        namesz = xnh_namesz;
        descsz = xnh_descsz;

        if ((namesz == 0) && (descsz == 0)) {
                /*
                 * We're out of note headers.
                 */
                return (offset >= size) ? offset : size;
        }

        if (namesz & 0x80000000) {
            (void)file_printf(ms, ", bad note name size %#lx",
                (unsigned long)namesz);
            return 0;
        }

        if (descsz & 0x80000000) {
            (void)file_printf(ms, ", bad note description size %#lx",
                (unsigned long)descsz);
            return 0;
        }

        noff = offset;
        doff = ELF_ALIGN(offset + namesz);

        if (offset + namesz > size) {
                /*
                 * We're past the end of the buffer.
                 */
                return doff;
        }

        offset = ELF_ALIGN(doff + descsz);
        if (doff + descsz > size) {
                /*
                 * We're past the end of the buffer.
                 */
                return (offset >= size) ? offset : size;
        }


        if ((*flags & FLAGS_DID_OS_NOTE) == 0) {
                if (do_os_note(ms, nbuf, xnh_type, swap,
                    namesz, descsz, noff, doff, flags))
                        return offset;
        }

        if ((*flags & FLAGS_DID_BUILD_ID) == 0) {
                if (do_bid_note(ms, nbuf, xnh_type, swap,
                    namesz, descsz, noff, doff, flags))
                        return offset;
        }

        if ((*flags & FLAGS_DID_NETBSD_PAX) == 0) {
                if (do_pax_note(ms, nbuf, xnh_type, swap,
                    namesz, descsz, noff, doff, flags))
                        return offset;
        }

        if ((*flags & FLAGS_DID_CORE) == 0) {
                if (do_core_note(ms, nbuf, xnh_type, swap,
                    namesz, descsz, noff, doff, flags, size, clazz))
                        return offset;
        }

        if ((*flags & FLAGS_DID_AUXV) == 0) {
                if (do_auxv_note(ms, nbuf, xnh_type, swap,
                        namesz, descsz, noff, doff, flags, size, clazz,
                        fd, ph_off, ph_num, fsize))
                        return offset;
        }

        if (namesz == 7 && strcmp((char *)&nbuf[noff], "NetBSD") == 0) {
                if (descsz > 100)
                        descsz = 100;
                switch (xnh_type) {
                case NT_NETBSD_VERSION:
                        return offset;
                case NT_NETBSD_MARCH:
                        if (*flags & FLAGS_DID_NETBSD_MARCH)
                                return offset;
                        *flags |= FLAGS_DID_NETBSD_MARCH;
                        if (file_printf(ms, ", compiled for: %.*s",
                            (int)descsz, (const char *)&nbuf[doff]) == -1)
                                return offset;
                        break;
                case NT_NETBSD_CMODEL:
                        if (*flags & FLAGS_DID_NETBSD_CMODEL)
                                return offset;
                        *flags |= FLAGS_DID_NETBSD_CMODEL;
                        if (file_printf(ms, ", compiler model: %.*s",
                            (int)descsz, (const char *)&nbuf[doff]) == -1)
                                return offset;
                        break;
                default:
                        if (*flags & FLAGS_DID_NETBSD_UNKNOWN)
                                return offset;
                        *flags |= FLAGS_DID_NETBSD_UNKNOWN;
                        if (file_printf(ms, ", note=%u", xnh_type) == -1)
                                return offset;
                        break;
                }
                return offset;
        }

        return offset;
}

